insert into public.support_kb(q,a,k,source) values
('Jak se bezpečně potkat?','První schůzku dej na veřejné místo, řekni kamarádovi, kam a s kým jdeš, a dopravu si zařiď sám/sama. Nikdy nikomu z aplikace neposílej peníze ani kódy – i kdyby to znělo naléhavě. Hledej modrý odznak ověřeného profilu. Když ti někdo není příjemný, zablokuj ho a nahlas (tři tečky v chatu).',array['bezpe','rande','schůzk','schuzk','podvod','peníze','penize']::text[],'faq'),
('Jak funguje Boost?','Boost tě na 30 minut posune mezi první profily, které lidé v okolí uvidí – obvykle to znamená mnohem víc zobrazení a lajků. Spustíš ho bleskem ⚡ nahoře v Objevuj. Gold má 1 Boost měsíčně v ceně, Platinum 3; jinak stojí 500 coinů.',array['boost','zviditel','víc lajk','vic lajk']::text[],'faq'),
('Co jsou Boost Coiny?','Coiny jsou měna v Plamínku. Koupíš je v Profil → ikona coinu. Utratíš je za Boost (500), Super Like navíc (100), odhalení lajku nebo zprávy (150), vrácení swipu (50) a zprávu navíc (100). Za ověření profilu dostaneš 500 coinů zdarma.',array['coin','mince','měna','mena']::text[],'faq'),
('Předplatné a platby','Předplatné spravuje Google Play. Zrušení: aplikace Obchod Play → ikona profilu → Platby a předplatné → Předplatná → Plamínek → Zrušit. Placené funkce ti zůstanou do konce zaplaceného období. Když se ti předplatné po nákupu neukázalo, otevři Předplatné a klepni na „Obnovit nákup“.',array['předplat','predplat','zrušit','zrusit','gold','platinum','plus','platb','peníze','penize','vrátit','vratit','refund']::text[],'faq'),
('Ověření profilu','V Profilu klepni na „Ověř se selfie“, vyfoť se se zadaným gestem a odešli. Kontrolujeme ručně, obvykle do 24 hodin. Ověřený profil dostane fialový štít a 500 coinů jako odměnu.',array['ověř','over','selfie','fajfk','odznak']::text[],'faq'),
('V Objevuj nikoho nevidím','Zkus v Objevuj → Filtry rozšířit věk a vzdálenost a zkontroluj, že máš povolenou polohu (Profil → Upravit profil → Poloha). Pokud máš profil pozastavený, zapni ho v Nastavení. Noví lidé přibývají každý den.',array['nikoho','nikdo','žádn','zadn','prázdn','prazdn','objevuj']::text[],'faq'),
('Nechodí mi upozornění','Otevři Profil → Nastavení a zapni „Push notifikace“. Pak zkontroluj v telefonu Nastavení → Aplikace → Plamínek → Oznámení, že jsou povolená. Na některých telefonech pomůže vypnout pro Plamínek úsporu baterie.',array['notifik','upozorn','oznámen','oznamen']::text[],'faq'),
('Smazání nebo pozastavení účtu','Profil → Nastavení → Smazat účet. Smaže se profil, fotky, shody i zprávy a nejde to vrátit. Pokud si chceš jen odpočinout, zapni v Nastavení „Pozastavit profil“ – nikdo nový tě neuvidí a o nic nepřijdeš.',array['smaz','smaž','zruš účet','zrus ucet','odstran','pauz','pozastav']::text[],'faq'),
('Proč nejde poslat Instagram nebo číslo?','Kontakty (Instagram, telefon, e-mail, odkazy) si můžete poslat, až si se shodou napíšete aspoň 10 zpráv. S předplatným Plus a vyšším je pošleš hned. V první zprávě bez shody je poslat nejde. Chráníme tím všechny před spamem, podvodníky a falešnými profily. S předplatným si můžeš Instagram dát i do profilu.',array['kontakt','instagram','insta','telefon','číslo','cislo','odkaz']::text[],'faq'),
('Někdo mě obtěžuje','V profilu nebo chatu toho člověka klepni na ⋯ → Blokovat nebo Nahlásit. Nahlášení kontrolujeme ručně. Nikdy nikomu neposílej peníze ani kódy z SMS. Když se cítíš v ohrožení, obrať se na policii.',array['nahlás','nahlas','obtěž','obtez','podvod','fake','falešn','falesn','blok','vyhrož','vyhroz']::text[],'faq'),
('Změna hesla','Heslo změníš v Profil → Nastavení → Změnit heslo. Pokud ho nevíš, na přihlašovací obrazovce klepni na „Zapomněl(a) jsi heslo?“ a pošleme ti odkaz.',array['heslo','hesla','heslem','password']::text[],'faq'),
('Problém s přihlášením','Na přihlašovací obrazovce klepni na „Zapomenuté heslo“ – pošleme ti odkaz. Pokud ses registroval(a) přes Google nebo Facebook, přihlas se stejným tlačítkem. E-mail a heslo změníš v Profil → Nastavení.',array['přihl','prihl','login','e-mail','email']::text[],'faq'),
('Jak napsat někomu bez shody?','V Objevuj klepni na ✈️ a napiš zprávu. Zdarma můžeš napsat 1 člověku denně (Gold 3, Platinum 5), další zprávy stojí 100 coinů. Když ti dotyčný odpoví, vznikne shoda.',array['zpráv','zprav','napsat','bez shody','psát','psat']::text[],'faq'),
('Co je Souznění?','Souznění je srdíčko s procenty v detailu profilu. Počítá, jak moc si sedíte: společné záliby (víc váží ty, které oba milujete ❤️), jak rádi odpočíváte, co oba hledáte, typ osobnosti a pro zábavu i hvězdy. Dvě kolečka ukazují, co máte společné a v čem se lišíte. Čím víc toho v profilu vyplníš, tím přesnější je.',array['souzn','shod','procent','srdíčk','srdick','kolečk','kolick','kompatib']::text[],'faq'),
('Proč mi to nepustilo fotku?','Plamínek automaticky kontroluje fotky v profilu i v chatu. Plavky a spodní prádlo jsou v pořádku, nahé a sexuální fotky ne. Taková fotka se neodešle; při opakovaném pokusu se účet trvale zablokuje. Když si myslíš, že jde o omyl, napiš nám sem a podíváme se na to.',array['fotk','fotky','obráz','obraz','nahr','neodešl','neodesl','nahot']::text[],'faq'),
('Jak poznám, kdo to myslí vážně?','Každý v profilu vybírá, jak to myslí: Vážný vztah, Uvidíme, Kamarádství, Společník na aktivity nebo Nechci se vázat. Je to vidět barevným štítkem hned na kartě. Lidi, kteří hledají něco nezávazného, ti při hledání vážného vztahu ukazujeme mnohem méně. Na čistě sexuální seznamování Plamínek není – takové profily nahlas a zablokujeme je.',array['vážn','vazn','nevěr','never','sex','vázat','vazat','kamarád','kamarad','společník','spolecnik','jak to myslí']::text[],'faq');
